    private static <M extends Message> void checkCase(Supplier<M> create, Function<M, Object> selected, Consumer<M> select, int[] at, String[] spelled, Object expected) {
        M message = create.get();
        String label = message.getClass().getSimpleName() + " selects " + expected + " by " + Arrays.toString(spelled);
        byte[] bytes = new byte[message.byteLength()];
        new Random(label.hashCode()).nextBytes(bytes);
        for (int index = 0; index < at.length; index++) {
            for (int character = 0; character < spelled[index].length(); character++) {
                bytes[at[index] + character] = (byte) spelled[index].charAt(character);
            }
        }
        expect(label + " decodes", message.parseFrom(bytes, 0));
        expect(label, selected.apply(message) == expected);
        expect(label + " encodes to its bytes", Arrays.equals(message.toBytes(), bytes));
        if (select != null) {
            M chosen = create.get();
            select.accept(chosen);
            M again = create.get();
            again.parseFrom(chosen.toBytes(), 0);
            expect(label + " when chosen", selected.apply(again) == expected);
        }
    }

    private static void expect(String check, boolean passed) {
        if (!passed) {
            failures++;
            System.out.println("FAIL " + check);
        }
    }
